def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]

    if v3 == 0:
        return None

    numerator = v1 + v2
    result = numerator / v3

    return {
        "value": result,
        "trace": {
            "numerator": numerator,
            "denominator": v3,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
